#
# One test per shim (docs/src/man/naming.md §17.3). This is the only file in the
# suite that calls the v0.4 names; everything else is on the v0.5 API.
#
# A forwarding shim warns before it forwards, so calling it with an argument the
# replacement cannot accept still proves that the shim exists, warns, and hands
# the call on. `Probe` is that argument.

using Test
using PETSc

struct DeprecationProbe end

# `@petsc_*_fn` read `PetscInt`/`PetscReal`/`PetscScalar` out of the calling module,
# so the expansion needs a module that has them.
module DeprecationMacroEnv
using PETSc
const PetscInt = Int64
const PetscReal = Float64
const PetscScalar = Float64
probe_simple(t, x, u, ctx) = nothing
probe_point(args...) = nothing
const Nf = 1
end

warns(f) = @test_logs (:warn, r"deprecated") match_mode = :any f()

# Call a shim in a way that reaches the warning but cannot go wrong afterwards.
function probe_shim(name::Symbol)
    f = getproperty(PETSc, name)
    warns() do
        try
            f(DeprecationProbe())
        catch
            # A MethodError from the replacement is the expected outcome: the
            # point of the call is that the warning was emitted on the way.
        end
    end
end

